document.addEventListener("DOMContentLoaded",function(){var t=document.getElementsByClassName("captcha-container")[0],i=t.getElementsByClassName("captcha-image")[0],r=i.getAttribute("src"),n=t.getElementsByClassName("captcha-input")[0],f=t.getElementsByClassName("captcha-icon-refresh")[0],u;i.addEventListener("load",function(){n.focus()});f.addEventListener("click",function(){n.value="";n.classList.remove("invalid");var t="";t=r.indexOf("?")===-1?r+"?t="+Date.now():r+"&t="+Date.now();i.setAttribute("src",t)});t.tagName.toUpperCase()==="FORM"&&(u=t,u.addEventListener("submit",function(t){n.value?n.classList.remove("invalid"):(t.preventDefault(),n.classList.contains("invalid")||n.classList.add("invalid"))}))});